def transform(grid):
    """Mark with 1 the missing trailing cells of a repeated horizontal motif."""
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not active:
        return out

    # Simple bars: extend each partial left-aligned bar to the length of the
    # longest solid bar. This covers the examples with isolated horizontal bars.
    bar_mode = True
    bar_color = None
    lengths = {}
    for r in active:
        row = grid[r]
        pos = [c for c, v in enumerate(row) if v != bg]
        if pos != list(range(len(pos))):
            bar_mode = False
            break
        colors = {row[c] for c in pos}
        if len(colors) != 1:
            bar_mode = False
            break
        color = next(iter(colors))
        if bar_color is None:
            bar_color = color
        elif color != bar_color:
            bar_mode = False
            break
        lengths[r] = len(pos)
    if bar_mode:
        width = max(lengths.values())
        for r in active:
            for c in range(lengths[r], width):
                if grid[r][c] == bg:
                    out[r][c] = 1
        return out

    # Repeated multi-row motif: use the first band as reference and mark only
    # the trailing background cells in its corresponding later copy.
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) >= 2:
        source, target = bands[0], bands[-1]
        if len(source) == len(target):
            for sr, tr in zip(source, target):
                last = max((c for c, v in enumerate(grid[tr]) if v != bg), default=-1)
                for c in range(last + 1, len(grid[tr])):
                    if grid[sr][c] != bg and grid[tr][c] == bg:
                        out[tr][c] = 1
    return out

